import java.io.*;

public class Main {
    // Doubly linked list with head AND tail pointers: all end ops are O(1).
    static class Node { int v; Node prev, next; Node(int v) { this.v = v; } }

    static DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
    static byte[] buf = new byte[32];

    static int readByte() throws IOException { return in.read(); }

    // read next token into buf, return length
    static int nextToken() throws IOException {
        int r = readByte();
        while (r <= 32 && r != -1) r = readByte();
        int n = 0;
        while (r > 32 && r != -1) { buf[n++] = (byte) r; r = readByte(); }
        return n;
    }

    static int ni() throws IOException {
        int r = readByte();
        while (r != '-' && (r < '0' || r > '9')) r = readByte();
        boolean neg = r == '-';
        if (neg) r = readByte();
        int x = 0;
        while (r >= '0' && r <= '9') { x = x * 10 + (r - '0'); r = readByte(); }
        return neg ? -x : x;
    }

    static Node head = null, tail = null;
    static int len = 0;

    static void pushFront(int v) {
        Node nd = new Node(v);
        nd.next = head;
        if (head != null) head.prev = nd; else tail = nd;
        head = nd;
        len++;
    }
    static void pushBack(int v) {
        Node nd = new Node(v);
        nd.prev = tail;
        if (tail != null) tail.next = nd; else head = nd;
        tail = nd;
        len++;
    }
    static void popFront() {
        Node nd = head;
        head = head.next;
        if (head != null) head.prev = null; else tail = null;
        len--;
    }
    static void popBack() {
        Node nd = tail;
        tail = tail.prev;
        if (tail != null) tail.next = null; else head = null;
        len--;
    }
    static Node at(int i) {
        Node cur;
        if (i <= len / 2) {
            cur = head;
            for (int s = 0; s < i; s++) cur = cur.next;
        } else {
            cur = tail;
            for (int s = len - 1; s > i; s--) cur = cur.prev;
        }
        return cur;
    }

    public static void main(String[] args) throws IOException {
        int q = ni();
        for (int t = 0; t < q; t++) {
            int n = nextToken();
            char c1 = (char) buf[1];
            if (c1 == 'u') {                    // push_front / push_back
                int v = ni();
                if (buf[5] == 'f') pushFront(v); else pushBack(v);
            } else if (c1 == 'o') {             // pop_front / pop_back
                if (buf[4] == 'f') popFront(); else popBack();
            } else if (buf[0] == 'i') {         // insert i v
                int i = ni(), v = ni();
                if (i == 0) { pushFront(v); continue; }
                if (i == len) { pushBack(v); continue; }
                Node cur = at(i);
                Node nd = new Node(v);
                nd.prev = cur.prev; nd.next = cur;
                cur.prev.next = nd;
                cur.prev = nd;
                len++;
            } else {                            // erase i
                int i = ni();
                if (i == 0) { popFront(); continue; }
                if (i == len - 1) { popBack(); continue; }
                Node cur = at(i);
                cur.prev.next = cur.next;
                cur.next.prev = cur.prev;
                len--;
            }
        }

        if (head == null) { System.out.println("EMPTY"); return; }
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (Node t = head; t != null; t = t.next) {
            if (!first) sb.append(' ');
            first = false;
            sb.append(t.v);
        }
        System.out.println(sb);
    }
}

solutions.python:
import sys

# Doubly linked list with head AND tail pointers: end ops are O(1),
# middle insert/erase walk from the closer end.


class Node:
    __slots__ = ('v', 'prev', 'next')

    def __init__(self, v):
        self.v = v
        self.prev = None
        self.next = None


data = sys.stdin.buffer.read().split()
pos = 0
q = int(data[pos]); pos += 1

head = tail = None
size = 0


def push_front(v):
    global head, tail, size
    nd = Node(v)
    nd.next = head
    if head is not None:
        head.prev = nd
    else:
        tail = nd
    head = nd
    size += 1


def push_back(v):
    global head, tail, size
    nd = Node(v)
    nd.prev = tail
    if tail is not None:
        tail.next = nd
    else:
        head = nd
    tail = nd
    size += 1


def pop_front():
    global head, tail, size
    nd = head
    head = nd.next
    if head is not None:
        head.prev = None
    else:
        tail = None
    size -= 1


def pop_back():
    global head, tail, size
    nd = tail
    tail = nd.prev
    if tail is not None:
        tail.next = None
    else:
        head = None
    size -= 1


def node_at(i):
    if i <= size // 2:
        cur = head
        for _ in range(i):
            cur = cur.next
    else:
        cur = tail
        for _ in range(size - 1 - i):
            cur = cur.prev
    return cur


for _ in range(q):
    op = data[pos]; pos += 1
    if op == b'push_front':
        push_front(int(data[pos])); pos += 1
    elif op == b'push_back':
        push_back(int(data[pos])); pos += 1
    elif op == b'pop_front':
        pop_front()
    elif op == b'pop_back':
        pop_back()
    elif op == b'insert':
        i = int(data[pos]); v = int(data[pos + 1]); pos += 2
        if i == 0:
            push_front(v)
        elif i == size:
            push_back(v)
        else:
            cur = node_at(i)
            nd = Node(v)
            nd.prev = cur.prev
            nd.next = cur
            cur.prev.next = nd
            cur.prev = nd
            size += 1
    else:  # erase
        i = int(data[pos]); pos += 1
        if i == 0:
            pop_front()
        elif i == size - 1:
            pop_back()
        else:
            cur = node_at(i)
            cur.prev.next = cur.next
            cur.next.prev = cur.prev
            size -= 1

out = []
t = head
while t is not None:
    out.append(str(t.v))
    t = t.next
print(' '.join(out) if out else 'EMPTY')

