        Node* p = &dummy;
        while (p->next && p->next->v < cur->v)  // strict < keeps it stable
            p = p->next;
        cur->next = p->next;                // splice: two writes
        p->next = cur;
        cur = nxt;
    }

    if (!dummy.next) { puts("EMPTY"); return 0; }
    string out;
    for (Node* t = dummy.next; t; t = t->next) {
        if (t != dummy.next) out += ' ';
        out += to_string(t->v);
    }
    puts(out.c_str());
    return 0;
}

