        Node tail = dummy;
        while (a != null || b != null || carry != 0) {
            int sum = carry;
            if (a != null) { sum += a.v; a = a.next; }
            if (b != null) { sum += b.v; b = b.next; }
            carry = sum / 10;
            tail.next = new Node(sum % 10);
            tail = tail.next;
        }
