    while (top > 0) {
        top--;
        struct Item it = lists[stk[top][0]].items[stk[top][1]];
        if (it.isList) {
            struct List *kids = &lists[it.listIdx];
            for (int k = kids->n - 1; k >= 0; k--) { stk[top][0] = it.listIdx; stk[top][1] = k; top++; }
